Section DsDtor.
Context {AC : AllocCeiling}.
Context {RRND : RunRandom}.
  Variable MI : MallocIface SEGS Ly.L.
  Variable ST : StaticsIface SEGS Ly.L.
  Hypothesis DN : diag_needs MI ST.

  #[local] Notation cfg fx R pc M model := (mkCfg (@mkst fx R (Z_to_bv 64 pc) M (seg_rom SEGS)) model).

  Definition kn_dtor (hdr : list kentry) : list kentry :=
    [KWr (SA (EVar 2) (-144)) (ELit 144);
     KWr (SA (EVar 10) 0) (ELit 392);
     KRange (EVar 2) (2 ^ 40) (2 ^ 47); KRange (EVar 10) (2 ^ 40) (2 ^ 47 - 392);
     KDisj (SA (EVar 10) 0) (ELit 392) (SA (EVar 2) (-144)) (ELit 144);
     KImg 0xe6000 0xee000;
     KWord (SA (EVar 10) 360) (N.to_nat 4) (EVar 32);
     KWord (SA (EVar 10) 320) (N.to_nat 8) (ELit 0);
     KWord (SA (EVar 10) 368) (N.to_nat 1) (ELit 0);
     KWord (SA (EVar 10) 336) (N.to_nat 1) (ELit 0);
     KWord (SA (EVar 10) 16) (N.to_nat 8) (ELit LOC_IMP);
     KWord (SA (EVar 10) 160) (N.to_nat 8) (ELit LOC_IMP);
     KWord (SA (EVar 10) 168) (N.to_nat 8) (ELit 0);
     KWord (SA (EVar 10) 176) (N.to_nat 8) (ELit 0);
     KWord (SA (EVar 10) 184) (N.to_nat 8) (ELit 0);
     KWord (SA (EVar 10) 200) (N.to_nat 8) (ELit 0);
     KWord (SA (EVar 10) 224) (N.to_nat 8) (ELit 0)] ++ hdr.
  Definition hdr_short : list kentry := [KWord (SA (EVar 10) 72) (N.to_nat 1) (ELit 44)].
  Definition hdr_long : list kentry := [KWord (SA (EVar 10) 72) (N.to_nat 8) (EVar 33); KWord (SA (EVar 10) 88) (N.to_nat 8) (EVar 34)].

  Section Call.
    Context {fx : FPState}.
    Variables (A : AS MI) (s : LibIface.SX ST) (R : bvmap 5 word) (M : mem) (model : Model).
    Variables (sp ret ds err len : Z) (B : list (Z * Z)) (K : TSet).
    Variables (m0 : sbuf) (pp0 hm0 fl fill : Z) (S : Z).
    Hypothesis CB : callB MI ST A s R M model sp ret S.
    Hypothesis HS : 336 + MALLOC_STACK MI <= S.
    Hypothesis ROC : ro_clear Ly.L M.
    Hypothesis Ha0 : getr R 10%bv = Z_to_bv 64 ds.
    Hypothesis DI0 : ds_inv A M ds err len B m0 pp0 hm0 fl fill.
    Hypothesis ABOVE : above_sp MI A sp ds 392.
    Hypothesis CONT : forall A' R' M' model',
        retB MI ST A' s R R' M' model model' ->
        blk_xfer B [] (live MI A) (live MI A') -> mdef M' ds 392 ->
        eff MI A A' M M' (sp - S, sp) (ds_foot ds B) ->
        srealizes SEGS (cfg fx R' ret M' model') K.

